package com.aistock.market.alert;
import com.aistock.common.*;import com.aistock.market.ingestion.CandidateRequestFilter;import com.aistock.market.marketlifecycle.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class AlertEvidenceReferenceHttpTest {
 @Test void internalMetadataIsAuthenticatedAndReturnsNoEvidenceBody()throws Exception{var jdbc=mock(JdbcTemplate.class);var id=UUID.randomUUID().toString();var raw=UUID.randomUUID().toString();when(jdbc.queryForList(anyString(),eq(id))).thenReturn(List.of(Map.of("evidence_id",id,"instrument_id","SH600030","raw_version_id",raw)));var mvc=MockMvcBuilders.standaloneSetup(new AlertEvidenceReferenceController(jdbc)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new CandidateRequestFilter("private",4096)).build();String uri="/internal/v1/market/alert-evidence-references/"+id;mvc.perform(get(uri)).andExpect(status().isUnauthorized());verifyNoInteractions(jdbc);mvc.perform(get(uri).header("X-Service-Token","private")).andExpect(status().isOk()).andExpect(jsonPath("$.data.length()").value(3)).andExpect(jsonPath("$.data.rawVersionId").value(raw)).andExpect(jsonPath("$.data.rawClose").doesNotExist());assertTrue(MarketEvidenceGate.purposes(uri).isEmpty());assertEquals(Set.of("ALERT_EVALUATION"),MarketEvidenceGate.purposes("/internal/v1/market/alert-evidence/versions/"+id));}
}
